// [WSCoop] Direct-IP dedicated-server clients have no online identity; use the id they reported.
if (WSIdentity::IsAnonymous(Player))
{
    FString WSName = WSIdentity::GetSaveName(Player);
    if (WSName.IsEmpty())
        WSName = f"ws_name_{Player.PlayerState.GetPlayerName().GetHash()}";
    Identity.Epic = WSName;
    Identity.Steam = WSName;
    WSDS::Info(f"Registered '{Player.PlayerState.GetPlayerName()}' with save name '{WSName}'");
    return true;
}
